 * Finds a dependency cycle, if any, using the depth-first search order the
 * specification pins down: tasks visited in ascending name order, and each
 * task's dependencies walked in ascending name order. Returns the cycle as
 * an array of names from the re-entered task back to itself, or `null` when
 * the graph is acyclic.
 */

export function findCycle(tasks, deps) {
  const names = [...tasks.keys()].sort()
  const visited = new Set()
  const onStack = new Set()

  for (const start of names) {
    if (visited.has(start)) continue

    const path = [start]
    onStack.add(start)
    const stack = [{ name: start, list: sortedDeps(deps, start), i: 0 }]

    while (stack.length > 0) {
      const frame = stack[stack.length - 1]
      if (frame.i < frame.list.length) {
        const dep = frame.list[frame.i++]
        if (onStack.has(dep)) {
          const idx = path.indexOf(dep)
          return path.slice(idx).concat(dep)
        }
        if (!visited.has(dep)) {
          path.push(dep)
          onStack.add(dep)
          stack.push({ name: dep, list: sortedDeps(deps, dep), i: 0 })
        }
      } else {
        stack.pop()
        path.pop()
        onStack.delete(frame.name)
        visited.add(frame.name)
      }
    }
  }

  return null
}

function sortedDeps(deps, name) {
  return [...(deps.get(name) || [])].sort()
}
"}

