 * Computes each task's unlimited-worker start, finish and wave depth in a
 * single topological (Kahn's algorithm) pass. The graph is assumed acyclic;
 * callers must run cycle detection first.
 */

export function computeTiming(tasks, deps) {
  const dependents = new Map()
  const indegree = new Map()
  for (const name of tasks.keys()) {
    dependents.set(name, [])
    indegree.set(name, 0)
  }
  for (const [name, depSet] of deps) {
    indegree.set(name, depSet.size)
    for (const dep of depSet) dependents.get(dep).push(name)
  }

  const start = new Map()
  const finish = new Map()
  const depth = new Map()

  const remaining = new Map(indegree)
  const queue = [...tasks.keys()].filter((name) => remaining.get(name) === 0)

  for (let i = 0; i < queue.length; i++) {
    const name = queue[i]
    const depSet = deps.get(name) || new Set()

    let s = 0
    let d = 0
    for (const dep of depSet) {
      s = Math.max(s, finish.get(dep))
      d = Math.max(d, depth.get(dep) + 1)
    }

    start.set(name, s)
    finish.set(name, s + tasks.get(name))
    depth.set(name, d)

    for (const next of dependents.get(name)) {
      const left = remaining.get(next) - 1
      remaining.set(next, left)
      if (left === 0) queue.push(next)
    }
  }

  return { start, finish, depth }
}
"}

