{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e12-self-review-sonnet-t5t6-20260927T000002Z/cell-s7xveJ/src/pack.js","content":"/**
 * Simulates the build graph on a fixed number of workers, following the
 * greedy-at-every-instant rule: whenever a worker is free and some task is
 * ready, start the highest-priority ready task (ties broken by ascending
 * name) on the lowest-indexed free worker, then re-check before advancing
 * time to the next worker-free instant.
 */

export function packSchedule(tasks, deps, priority, numWorkers) {
  const names = [...tasks.keys()]
  const total = names.length

  const workerFreeAt = new Array(numWorkers).fill(0)
  const workerLog = Array.from({ length: numWorkers }, () => [])
  const finishedAt = new Map()
  const started = new Set()

  let time = 0
  let done = 0

  while (done < total) {
    let progressed = true
    while (progressed) {
      progressed = false

      let freeWorker = -1
      for (let i = 0; i < numWorkers; i++) {
        if (workerFreeAt[i] <= time) {
          freeWorker = i
          break
        }
      }
      if (freeWorker === -1) break

      let best = null
      for (const name of names) {
        if (started.has(name)) continue
        if (!isReady(deps.get(name), finishedAt, time)) continue
        if (best === null) {
          best = name
        } else {
          const p = priority.get(name)
          const pBest = priority.get(best)
          if (p > pBest || (p === pBest && name < best)) best = name
        }
      }
      if (best === null) break

      const taskStart = time
      const taskFinish = taskStart + tasks.get(best)
      workerLog[freeWorker].push({ name: best, start: taskStart, finish: taskFinish })
      workerFreeAt[freeWorker] = taskFinish
      finishedAt.set(best, taskFinish)
      started.add(best)
      done++
      progressed = true
    }

    if (done >= total) break

    let next = Infinity
    for (let i = 0; i < numWorkers; i++) {
      if (workerFreeAt[i] > time) next = Math.min(next, workerFreeAt[i])
    }
    time = next
  }

  const makespan = finishedAt.size === 0 ? 0 : Math.max(...finishedAt.values())
  return { workerLog, makespan }
}

function isReady(depSet, finishedAt, time) {
  if (!depSet) return true
  for (const dep of depSet) {
    const finish = finishedAt.get(dep)
    if (finish === undefined || finish > time) return false
  }
  return true
}
"}

